"""Adapter para qualquer API compativel com OpenAI Chat Completions.

Cobre Groq, Ollama (self-hosted), OpenAI, OpenRouter, vLLM... so muda base_url,
api_key e model. E o unico arquivo que conhece o formato OpenAI.
"""
from __future__ import annotations

import json
from typing import Any, Sequence

from openai import OpenAI, OpenAIError

from .base import ChatMessage, LLMError, LLMReply, ToolCall, ToolSpec


class OpenAICompatProvider:
    def __init__(self, *, base_url: str, api_key: str, model: str, timeout_s: float = 30.0,
                 temperature: float = 0.2) -> None:
        self.name = f"openai-compat:{model}"
        self._model = model
        self._temperature = temperature
        self._client = OpenAI(base_url=base_url, api_key=api_key, timeout=timeout_s, max_retries=2)

    def complete(self, messages: Sequence[ChatMessage], tools: Sequence[ToolSpec]) -> LLMReply:
        try:
            resp = self._client.chat.completions.create(
                model=self._model,
                messages=[_to_wire(m) for m in messages],  # type: ignore[arg-type]
                tools=[_tool_to_wire(t) for t in tools] or None,  # type: ignore[arg-type]
                temperature=self._temperature,
            )
        except OpenAIError as e:
            raise LLMError(f"{type(e).__name__}: {e}") from e

        if not resp.choices:
            raise LLMError("resposta sem choices")
        msg = resp.choices[0].message
        calls: list[ToolCall] = []
        for tc in msg.tool_calls or []:
            try:
                args = json.loads(tc.function.arguments or "{}")
            except json.JSONDecodeError as e:
                raise LLMError(f"argumentos de ferramenta invalidos: {tc.function.arguments!r}") from e
            calls.append(ToolCall(id=tc.id, name=tc.function.name, arguments=args))
        return LLMReply(text=msg.content, tool_calls=tuple(calls))


def _tool_to_wire(t: ToolSpec) -> dict[str, Any]:
    return {"type": "function",
            "function": {"name": t.name, "description": t.description, "parameters": t.parameters}}


def _to_wire(m: ChatMessage) -> dict[str, Any]:
    if m.role == "tool":
        return {"role": "tool", "tool_call_id": m.tool_call_id, "content": m.content or ""}
    out: dict[str, Any] = {"role": m.role, "content": m.content}
    if m.tool_calls:
        out["tool_calls"] = [
            {"id": c.id, "type": "function",
             "function": {"name": c.name, "arguments": json.dumps(c.arguments, ensure_ascii=False)}}
            for c in m.tool_calls
        ]
    return out

