"""Rastreio: um evento por linha (JSONL), sempre com id e status.

Cada mensagem tem message_id, cada cotacao tem quote_id e cada tentativa HTTP
vira um evento proprio (attempt, status, latency_ms). Todo texto passa por
pii.mask antes de ser gravado.
"""
from __future__ import annotations

import datetime as dt
import json
import threading
from pathlib import Path
from typing import Any, Protocol

from .pii import mask


class Tracer(Protocol):
    def emit(self, event: str, **fields: Any) -> None: ...


class JsonlTracer:
    def __init__(self, path: Path) -> None:
        path.parent.mkdir(parents=True, exist_ok=True)
        self.path = path
        self._lock = threading.Lock()

    def emit(self, event: str, **fields: Any) -> None:
        record = {"ts": dt.datetime.now(dt.timezone.utc).isoformat(timespec="milliseconds"),
                  "event": event, **{k: _safe(v) for k, v in fields.items()}}
        line = json.dumps(record, ensure_ascii=False)
        with self._lock, self.path.open("a", encoding="utf-8") as f:
            f.write(line + "\n")


class MemoryTracer:
    """Para testes."""

    def __init__(self) -> None:
        self.events: list[dict[str, Any]] = []

    def emit(self, event: str, **fields: Any) -> None:
        self.events.append({"event": event, **{k: _safe(v) for k, v in fields.items()}})


def _safe(v: Any) -> Any:
    if isinstance(v, str):
        return mask(v)
    if isinstance(v, dict):
        return {k: _safe(x) for k, x in v.items()}
    if isinstance(v, (list, tuple)):
        return [_safe(x) for x in v]
    return v

