"""Cliente da /quote com tratamento explicito de falha.

Classificacao (a decisao mais importante deste arquivo):
  200            -> QuoteOk
  422            -> QuoteRefused   (regra de negocio: NAO repetir, a resposta e final)
  400 / outro 4xx-> QuoteInvalid   (bug nosso no payload: NAO repetir)
  5xx / timeout / erro de conexao -> transitorio: repete com backoff + jitter;
                    esgotou as tentativas -> QuoteUnavailable

Timeout por tentativa (3 s) e menor que a lentidao simulada (8 s): uma chamada lenta
vira nova tentativa em vez de prender o lead.
"""
from __future__ import annotations

import random
import time
import uuid
from dataclasses import dataclass
from typing import Any, Callable, Protocol

import httpx

from .trace import Tracer


@dataclass(frozen=True)
class QuoteOk:
    quote_id: str
    data: dict[str, Any]
    attempts: int


@dataclass(frozen=True)
class QuoteRefused:
    quote_id: str
    motivo: str
    attempts: int


@dataclass(frozen=True)
class QuoteInvalid:
    quote_id: str
    detalhe: str
    attempts: int


@dataclass(frozen=True)
class QuoteUnavailable:
    quote_id: str
    last_error: str
    attempts: int


QuoteResult = QuoteOk | QuoteRefused | QuoteInvalid | QuoteUnavailable


class QuoteGateway(Protocol):
    def quote(self, payload: dict[str, Any], *, conversation_id: str) -> QuoteResult: ...
    def plans(self) -> dict[str, Any]: ...


class QuoteClient:
    def __init__(self, base_url: str, tracer: Tracer, *, timeout_s: float = 3.0, max_attempts: int = 3,
                 backoff_base_s: float = 0.5, transport: httpx.BaseTransport | None = None,
                 sleep: Callable[[float], None] = time.sleep, rng: random.Random | None = None) -> None:
        self._http = httpx.Client(base_url=base_url, timeout=timeout_s, transport=transport)
        self._tracer = tracer
        self._max_attempts = max_attempts
        self._backoff = backoff_base_s
        self._sleep = sleep
        self._rng = rng or random.Random()

    def plans(self) -> dict[str, Any]:
        r = self._http.get("/planos")
        r.raise_for_status()
        return r.json()

    def quote(self, payload: dict[str, Any], *, conversation_id: str) -> QuoteResult:
        quote_id = f"q_{uuid.uuid4().hex[:12]}"
        last_error = ""
        for attempt in range(1, self._max_attempts + 1):
            t0 = time.perf_counter()
            status: int | str
            try:
                r = self._http.post("/quote", json=payload)
                status = r.status_code
            except httpx.TimeoutException:
                status, r = "timeout", None
            except httpx.TransportError as e:
                status, r = f"conn_error:{type(e).__name__}", None
            latency_ms = round((time.perf_counter() - t0) * 1000)
            self._tracer.emit("quote_attempt", conversation_id=conversation_id, quote_id=quote_id,
                              attempt=attempt, status=status, latency_ms=latency_ms)

            if r is not None and r.status_code == 200:
                return QuoteOk(quote_id, r.json(), attempt)
            if r is not None and r.status_code == 422:
                return QuoteRefused(quote_id, _json(r).get("motivo", "cotacao recusada"), attempt)
            if r is not None and 400 <= r.status_code < 500:
                return QuoteInvalid(quote_id, str(_json(r)), attempt)

            last_error = str(status)
            if attempt < self._max_attempts:
                delay = self._backoff * 2 ** (attempt - 1) + self._rng.uniform(0, self._backoff / 2)
                self._sleep(delay)
        return QuoteUnavailable(quote_id, last_error, self._max_attempts)


def _json(r: httpx.Response) -> dict[str, Any]:
    try:
        body = r.json()
        return body if isinstance(body, dict) else {"body": body}
    except ValueError:
        return {"body": r.text[:200]}

